+#[test]
+fn setup_alignment_wcs_and_source_changes_update_cached_heights() {
+    let mut state = fixture();
+    state.history.execute(
+        &state.world,
+        CreateSetup::new(&state.world, Some("Setup1"), None).unwrap(),
